def f(n):
    result = []

    for i in range(1, n + 1):
        if i % 2 == 0:
            # Calculate factorial of i
            fact = 1
            for j in range(1, i + 1):
                fact *= j
            result.append(fact)
        else:
            # Calculate sum from 1 to i
            summation = (i * (i + 1)) // 2
            result.append(summation)

    return result
